#!/usr/bin/env php
<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
require_once __DIR__.'/../includes/push_notifications.php';
$apply=in_array('--apply',$argv,true);$db=push_db();$dir=push_config()['legacy_store'];$report=['mode'=>$apply?'apply':'dry-run','files'=>0,'subscriptions_imported'=>0,'deliveries_imported'=>0,'invalid'=>0,'orphaned'=>0,'already_complete'=>false,'backups'=>[]];
$done=$db->prepare("SELECT meta_value FROM push_migration_meta WHERE meta_key='legacy_json_completed'");$done->execute();if($done->fetchColumn()!==false){$report['already_complete']=true;echo json_encode($report,JSON_UNESCAPED_SLASHES).PHP_EOL;exit(0);}
try{
 $read=function(string $name)use($dir,&$report):array{$path=$dir.'/'.$name;if(!is_file($path))return [];$report['files']++;$raw=file_get_contents($path);if($raw===false)throw new RuntimeException('Legacy push file cannot be read.');$data=json_decode($raw,true,32,JSON_THROW_ON_ERROR);if(!is_array($data)||!array_is_list($data))throw new RuntimeException('Legacy push file must contain a JSON array.');return [$path,$raw,$data];};
 $subsFile=$read('subscriptions.json');$deliveriesFile=$read('deliveries.json');$idMap=[];
 if($apply)$db->beginTransaction();
 foreach(($subsFile[2]??[]) as $row){if(!is_array($row)||!is_int($row['user_id']??null)&&!ctype_digit((string)($row['user_id']??''))||!preg_match('/^[a-f0-9]{64}$/D',(string)($row['endpoint_hash']??''))||!in_array($row['status']??'', ['active','revoked','expired','invalid'],true)||!isset($row['endpoint'],$row['p256dh'],$row['auth'])||!str_starts_with((string)$row['endpoint'],'v1.')||!str_starts_with((string)$row['p256dh'],'v1.')||!str_starts_with((string)$row['auth'],'v1.')){$report['invalid']++;continue;}$uid=(int)$row['user_id'];if(!push_employee_active($db,$uid)){$report['orphaned']++;continue;}$q=$db->prepare('SELECT id,updated_at FROM push_subscriptions WHERE endpoint_hash=?');$q->execute([$row['endpoint_hash']]);$existing=$q->fetch(PDO::FETCH_ASSOC);if($existing){$idMap[(string)($row['id']??'')]=(int)$existing['id'];continue;}if($apply){$s=$db->prepare("INSERT INTO push_subscriptions(user_id,endpoint_hash,endpoint_encrypted,p256dh_encrypted,auth_encrypted,envelope_version,device_label,user_agent,status,created_at,updated_at,last_used_at,revoked_at,failure_count,last_failure_category) VALUES(?,?,?,?,?,1,?,?,?,?,?,?,?,?,?)");$s->execute([$uid,$row['endpoint_hash'],$row['endpoint'],$row['p256dh'],$row['auth'],push_safe_text((string)($row['label']??''),60)?:'Imported browser',push_safe_text((string)($row['user_agent']??''),160),$row['status'],(string)($row['created_at']??gmdate('Y-m-d H:i:s')),(string)($row['updated_at']??$row['created_at']??gmdate('Y-m-d H:i:s')),$row['last_used_at']??null,$row['revoked_at']??null,max(0,(int)($row['failure_count']??0)),push_safe_text((string)($row['last_failure_code']??''),40)?:null]);$idMap[(string)($row['id']??'')]=(int)$db->lastInsertId();}$report['subscriptions_imported']++;}
 foreach(($deliveriesFile[2]??[]) as $row){$nid=(int)($row['notification_id']??0);$sid=$idMap[(string)($row['subscription_id']??'')]??0;$q=$db->prepare('SELECT 1 FROM portal_notifications WHERE id=?');$q->execute([$nid]);if(!$nid||!$sid||!$q->fetchColumn()){$report['orphaned']++;continue;}$status=match($row['status']??'pending'){'sent'=>'sent','invalid'=>'invalid','skipped'=>'skipped',default=>'pending'};if($apply){$s=$db->prepare("INSERT OR IGNORE INTO push_deliveries(notification_id,subscription_id,status,attempt_count,next_attempt_at,created_at,updated_at,sent_at) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$nid,$sid,$status,max(0,(int)($row['attempt_count']??0)),$row['next_attempt_at']??null,$row['created_at']??gmdate('Y-m-d H:i:s'),$row['updated_at']??$row['created_at']??gmdate('Y-m-d H:i:s'),$row['sent_at']??null]);$report['deliveries_imported']+=$s->rowCount();}else $report['deliveries_imported']++;}
 if($apply){$stamp=gmdate('YmdHis');foreach([$subsFile,$deliveriesFile] as $f)if($f){$backup=$f[0].'.backup-'.$stamp;$bytes=file_put_contents($backup,$f[1],LOCK_EX);if($bytes!==strlen($f[1]))throw new RuntimeException('Legacy backup failed.');chmod($backup,0400);chmod($f[0],0400);$checksum=hash('sha256',$f[1]);$report['backups'][]=['file'=>basename($backup),'sha256'=>$checksum];$m=$db->prepare("INSERT OR REPLACE INTO push_migration_meta(meta_key,meta_value,updated_at) VALUES(?,?,datetime('now'))");$m->execute(['legacy_checksum_'.basename($f[0]),$checksum]);}$m=$db->prepare("INSERT INTO push_migration_meta(meta_key,meta_value,updated_at) VALUES('legacy_json_completed',?,datetime('now'))");$m->execute([gmdate(DATE_ATOM)]);$db->commit();}
 echo json_encode($report,JSON_UNESCAPED_SLASHES).PHP_EOL;
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,json_encode($report+['status'=>'invalid-legacy-state']).PHP_EOL);exit(2);}
